      "colRecipe": "Rezept",
      "colSkill": "Fertigkeit",
      "colSource": "Quelle",
      "colStation": "Station",
      "colMaterials": "Materialien",
      "colQuality": "QualitÃ¤t",
      "colGain": "Gewinn schwindet ab",
      "colMaterial": "Material",
